    'The app-relative path public MCP clients connect to, such as `/mcp`.' => 'المسار النسبي للتطبيق الذي يتصل به عملاء MCP العامون، مثل `/mcp`.',
    'The app-relative path to give MCP clients that sign in with OAuth. It always requires an access token, so clients can discover how to sign in.' => 'المسار النسبي للتطبيق الذي يُعطى لعملاء MCP الذين يسجلون الدخول باستخدام OAuth. يتطلب دائمًا رمز وصول، حتى يتمكن العملاء من اكتشاف كيفية تسجيل الدخول.',
