    'The template receives `element` and `static` variables. Its output is sanitized and displayed as non-interactive content; form controls, scripts, and registered assets are not supported.' => 'يتلقى القالب المتغيرين `element` و`static`. يتم تنقية مخرجاته وعرضها كمحتوى غير تفاعلي؛ ولا يتم دعم عناصر التحكم في النماذج والبرامج النصية والأصول المسجّلة.',
