    'The {numTargets, plural, =1{{targetTypeSingular} is} other{{targetTypePlural} are}} referenced by fields in {numSources, number} other {numSources, plural, =1{element} other{elements}}.' => '{numTargets, plural, =1{يُشار إلى {targetTypeSingular}} other{يُشار إلى {targetTypePlural}}} بواسطة حقول في {numSources, number} {numSources, plural, =1{عنصر آخر} few{عناصر أخرى} many{عنصرًا آخر} other{عنصر آخر}}.',
