    'When enabled, site requests will return a service unavailable response and queued jobs will pause.' => 'عند التمكين، ستُرجع طلبات الموقع استجابة “الخدمة غير متاحة” وسيتم إيقاف المهام في قائمة الانتظار مؤقتًا.',
    'When someone replaces a file, the record of who uploaded the file will be updated as well.' => 'عندما يقوم شخص ما باستبدال ملف، سيتم تحديث سجل من قام بتحميل الملف.',
    'Where assets should be stored (relative to **Asset Location**) when they are uploaded directly to the field.' => 'مكان تخزين الأصول (بالنسبة إلى **موقع الأصول**) عند تحميلها مباشرة إلى الحقل.',
