    'Whether HTML should be encoded before rendering the Markdown.' => 'ما إذا كان يجب ترميز HTML قبل عرض Markdown.',
    'Whether authors should be able to choose which time zone the time is in.' => 'ما إذا كان يجب أن يكون المؤلفون قادرين على اختيار المنطقة الزمنية التي يقع فيها الوقت أم لا.',
    'Whether authors should be able to upload files directly to the field, rather than requiring them to select/upload assets via the selection modal.' => 'ما إذا كان يجب أن يكون المؤلفون قادرين على تحميل الملفات مباشرة إلى الحقل، بدلاً من مطالبتهم بتحديد / تحميل الأصول عبر النافذة الشكلية.',
    'Whether buttons should only show their icons, hiding their text labels.' => 'ما إذا كانت الأزرار يجب أن تعرض أيقوناتها فقط وتخفي التسميات النصية.',
    'Whether card views which include this field should show the custom ON/OFF labels, rather than the field name.' => 'ما إذا كان ينبغي أن تعرض طرق عرض البطاقات التي تتضمن هذا الحقل تسميات تشغيل/إيقاف مخصصة، بدلاً من اسم الحقل.',
    'Whether custom fields should be validated during public registration.' => 'ما إذا كان يجب التحقق من صحة الحقول المخصصة أثناء التسجيل العام.',
