    'Whether the field should only render inline Markdown, without wrapping paragraphs.' => 'ما إذا كان يجب أن يعرض الحقل Markdown المضمّن فقط، دون تغليف الفقرات.',
    'Whether the number of elements in this source should be shown beside it in the navigation.' => 'ما إذا كان يجب إظهار عدد العناصر في هذا المصدر بجانبه في التنقل.',
    'Whether the site menu should be shown for {type} selection modals.' => 'لتحديد ما إذا كان يجب عرض قائمة الموقع في نافذة {type} شكلية.',
    'Whether the structure of the related {type} should be maintained.' => 'ما إذا كان ينبغي الاحتفاظ بهيكل {type} ذي الصلة.',
    'Whether the table rows should be restricted to those defined by the “Default Values” setting.' => 'ما إذا كان ينبغي تقييد صفوف الجدول إلى تلك التي يحددها إعداد "القيم الافتراضية".',
    'Whether this can be dismissed by a user and not shown again.' => 'ما إذا كان يمكن للمستخدم تجاهل هذه الرسالة وعدم عرضها مرة أخرى.',
    'Whether to show entries that the user doesn’t have permission to view, per the “View other users’ entries” permission.' => 'ما إذا كان سيتم عرض الإدخالات التي لا يملك المستخدم إذنًا بعرضها، وفقًا لإذن "عرض إدخالات المستخدمين الآخرين".',
    'Whether to show files that the user doesn’t have permission to view, per the “View files uploaded by other users” permission.' => 'ما إذا كان سيتم عرض الملفات التي لا يملك المستخدم إذنًا بعرضها، وفقًا لإذن "عرض الملفات التي تم تحميلها بواسطة مستخدمين آخرين".',
    'Whether to show sections that the user doesn’t have permission to view.' => 'ما إذا كان سيتم عرض الأقسام التي لا يملك المستخدم إذنًا بعرضها.',
